 13	import type { CodexResponsesSseDataPayload } from "./sse.js";
 14	
 15	type CodexResponsesStreamJson = typeof Schema.Json.Type;
 16	
 17	export type CodexResponsesDecodedStreamEvent = Readonly<{
 18	  type: CodexResponsesStreamEventKind;
 19	  raw: CodexResponsesStreamJson;
 20	}>;
 21	
 22	export type CodexResponsesStreamInput =
 23	  | Readonly<{
 24	      _tag: "Event";
 25	      event: CodexResponsesDecodedStreamEvent;
 26	    }>
 27	  | Readonly<{ _tag: "Done" }>;
 28	
 29	export type CodexResponsesStreamSequenceState = Readonly<{
 30	  completed: boolean;
 31	  done: boolean;
 32	  eventCount: number;
 33	}>;
 34	
 35	export const initialCodexResponsesStreamSequenceState: CodexResponsesStreamSequenceState =
 36	  {
 37	    completed: false,
 38	    done: false,
 39	    eventCount: 0,
 40	  };
 41	
 42	export type CodexResponsesStreamDisposition =
 43	  | Readonly<{
 44	      _tag: "Continue";
 45	      event: CodexResponsesDecodedStreamEvent;
 46	    }>
 47	  | Readonly<{ _tag: "Completed" }>
 48	  | Readonly<{ _tag: "Done" }>;
 49	
 50	const streamError = (
 51	  operation: CodexResponsesStreamOperation,
 52	  message: string
 53	) => new CodexResponsesStreamError({ operation, message });
 54	
 55	export const decodeCodexResponsesStreamData = Effect.fn(
 56	  "CodexResponsesStreamEvents.decode"
 57	)(function* (
 58	  operation: CodexResponsesStreamOperation,
 59	  data: CodexResponsesSseDataPayload
 60	) {
 61	  const done = yield* Schema.decodeUnknownEffect(Schema.Literal("[DONE]"))(
 62	    data
 63	  ).pipe(Effect.option);
 64	  if (done._tag === "Some") {
 65	    const input: CodexResponsesStreamInput = { _tag: "Done" };
 66	    return input;
 67	  }
 68	
 69	  const raw = yield* Schema.decodeUnknownEffect(
 70	    Schema.fromJsonString(Schema.Json)
 71	  )(data).pipe(
 72	    Effect.mapError(() =>
 73	      streamError(operation, "Unable to decode Codex Responses stream JSON.")
 74	    )
 75	  );
 76	  const discriminator = yield* Schema.decodeUnknownEffect(
 77	    CodexResponsesStreamEventDiscriminator
 78	  )(raw).pipe(
 79	    Effect.mapError(() =>
 80	      streamError(operation, "Unable to decode Codex Responses stream event.")
 81	    )
 82	  );
 83	
 84	  const input: CodexResponsesStreamInput = {
 85	    _tag: "Event",
 86	    event: { type: discriminator.type, raw },
 87	  };
 88	  return input;
 89	});
 90	
 91	const decodeTerminalEvent = <A, I>(
 92	  operation: CodexResponsesStreamOperation,
 93	  schema: Schema.Codec<A, I>,
 94	  raw: CodexResponsesStreamJson
 95	) =>
 96	  Schema.decodeUnknownEffect(schema)(raw).pipe(
 97	    Effect.mapError(() =>
 98	      streamError(operation, "Unable to decode Codex Responses terminal event.")
 99	    )
100	  );
101	
102	export const advanceCodexResponsesStreamSequence = Effect.fn(
103	  "CodexResponsesStreamEvents.advance"
104	)(function* (
105	  operation: CodexResponsesStreamOperation,
106	  state: CodexResponsesStreamSequenceState,
107	  input: CodexResponsesStreamInput
108	) {
109	  if (input._tag === "Done") {
110	    if (!state.completed || state.done) {
111	      return yield* streamError(
112	        operation,
113	        "Codex Responses stream contained an out-of-order done marker."
114	      );
115	    }
116	    const disposition: CodexResponsesStreamDisposition = { _tag: "Done" };
117	    return {
118	      state: { ...state, done: true },
119	      disposition,
120	    };
121	  }
122	
123	  if (state.completed) {
124	    return yield* streamError(
125	      operation,
126	      "Codex Responses stream contained an event after completion."
127	    );
128	  }
129	
130	  const nextState = { ...state, eventCount: state.eventCount + 1 };
131	  return yield* Match.value(input.event.type).pipe(
132	    Match.when("response.completed", () =>
133	      decodeTerminalEvent(
134	        operation,
135	        CodexResponsesCompletedEvent,
136	        input.event.raw
137	      ).pipe(
138	        Effect.map(() => {
139	          const disposition: CodexResponsesStreamDisposition = {
140	            _tag: "Completed",
141	          };
142	          return {
143	            state: { ...nextState, completed: true },
144	            disposition,
145	          };
146	        })
147	      )
148	    ),
149	    Match.when("response.failed", () =>
150	      decodeTerminalEvent(
151	        operation,
152	        CodexResponsesFailedEvent,
153	        input.event.raw
154	      ).pipe(
155	        Effect.andThen(
156	          streamError(operation, "Codex Responses stream reported failure.")
157	        )
158	      )
159	    ),
160	    Match.when("response.incomplete", () =>
161	      decodeTerminalEvent(
162	        operation,
163	        CodexResponsesIncompleteEvent,
164	        input.event.raw
165	      ).pipe(
166	        Effect.andThen(
167	          streamError(operation, "Codex Responses stream was incomplete.")
168	        )
169	      )
170	    ),
171	    Match.when("error", () =>
172	      decodeTerminalEvent(
173	        operation,
174	        CodexResponsesErrorEvent,
175	        input.event.raw
176	      ).pipe(
177	        Effect.andThen(
178	          streamError(operation, "Codex Responses stream reported an error.")
179	        )
180	      )
181	    ),
182	    Match.orElse(() => {
183	      const disposition: CodexResponsesStreamDisposition = {
184	        _tag: "Continue",
185	        event: input.event,
186	      };
187	      return Effect.succeed({ state: nextState, disposition });
188	    })
189	  );
190	});

