  1	import { Chunk, Effect, Schema, Stream } from "effect";
  2	
  3	import type {
  4	  CodexHttpContentTypeHeader,
  5	  CodexResponsesStreamOperation,
  6	} from "./error-contracts.js";
  7	import { CodexResponsesStreamError } from "./errors.js";
  8	
  9	const codexResponsesSseLineMaxBytes = 1024 * 1024;
 10	const codexResponsesSseLineFragmentMaxCount = 4096;
 11	const codexResponsesSseEventMaxBytes = 1024 * 1024;
 12	const codexResponsesSseEventFieldMaxCount = 4096;
 13	
 14	type ByteInput =
 15	  | Readonly<{ _tag: "Bytes"; value: Uint8Array }>
 16	  | Readonly<{ _tag: "End" }>;
 17	
 18	type LineInput =
 19	  | Readonly<{
 20	      _tag: "Line";
 21	      value: string;
 22	      wireByteLength: number;
 23	    }>
 24	  | Readonly<{ _tag: "End" }>;
 25	
 26	type PendingCarriageReturnLine = Readonly<{
 27	  value: string;
 28	  contentByteLength: number;
 29	}>;
 30	
 31	type LineAccumulator = Readonly<{
 32	  byteLength: number;
 33	  fragmentCount: number;
 34	  parts: Chunk.Chunk<Uint8Array>;
 35	  pendingCarriageReturn: PendingCarriageReturnLine | undefined;
 36	}>;
 37	
 38	type LineStep = readonly [LineAccumulator, readonly LineInput[]];
 39	
 40	export const CodexResponsesSseDataPayload = Schema.String.pipe(
 41	  Schema.brand("CodexResponsesSseDataPayload")
 42	);
 43	export type CodexResponsesSseDataPayload =
 44	  typeof CodexResponsesSseDataPayload.Type;
 45	
 46	type DataAccumulator = Readonly<{
 47	  byteLength: number;
 48	  fieldCount: number;
 49	  parts: Chunk.Chunk<CodexResponsesSseDataPayload>;
 50	}>;
 51	
 52	type DataStep = readonly [
 53	  DataAccumulator,
 54	  readonly CodexResponsesSseDataPayload[],
 55	];
 56	
 57	const streamError = (
 58	  operation: CodexResponsesStreamOperation,
 59	  message: string
 60	) => new CodexResponsesStreamError({ operation, message });
 61	
 62	const decodeLine = (
 63	  operation: CodexResponsesStreamOperation,
 64	  parts: Chunk.Chunk<Uint8Array>,
 65	  byteLength: number
 66	) =>
 67	  Effect.try({
 68	    try: () => {
 69	      const bytes = new Uint8Array(byteLength);
 70	      let offset = 0;
 71	      for (const part of parts) {
 72	        bytes.set(part, offset);
 73	        offset += part.byteLength;
 74	      }
 75	      return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
 76	    },
 77	    catch: () =>
 78	      streamError(operation, "Unable to decode a Codex Responses SSE line."),
 79	  });
 80	
 81	const finishSseLines = (
 82	  operation: CodexResponsesStreamOperation,
 83	  state: LineAccumulator
 84	) =>
 85	  Effect.gen(function* finishSseLineFraming() {
 86	    if (state.byteLength > 0) {
 87	      return yield* streamError(
 88	        operation,
 89	        "Codex Responses SSE stream ended with an incomplete line."
 90	      );
 91	    }
 92	    const emitted: LineInput[] = [];
 93	    if (state.pendingCarriageReturn !== undefined) {
 94	      emitted.push({
 95	        _tag: "Line",
 96	        value: state.pendingCarriageReturn.value,
 97	        wireByteLength: state.pendingCarriageReturn.contentByteLength + 1,
 98	      });
 99	    }
100	    emitted.push({ _tag: "End" });
101	    const step: LineStep = [
102	      { ...state, pendingCarriageReturn: undefined },
103	      emitted,
104	    ];
105	    return step;
106	  });
107	
108	const splitSseBytes = (
109	  operation: CodexResponsesStreamOperation,
110	  state: LineAccumulator,
111	  input: Uint8Array
112	) =>
113	  Effect.gen(function* splitSseByteChunk() {
114	    const emitted: LineInput[] = [];
115	    let { parts } = state;
116	    let { byteLength } = state;
117	    let { fragmentCount } = state;
118	    let segmentStart = 0;
119	    let { pendingCarriageReturn } = state;
120	
121	    if (pendingCarriageReturn !== undefined && input.byteLength > 0) {
122	      const isCarriageReturnLineFeed = input[0] === 10;
123	      emitted.push({
124	        _tag: "Line",
125	        value: pendingCarriageReturn.value,
126	        wireByteLength:
127	          pendingCarriageReturn.contentByteLength +
128	          (isCarriageReturnLineFeed ? 2 : 1),
129	      });
130	      pendingCarriageReturn = undefined;
131	      segmentStart = isCarriageReturnLineFeed ? 1 : 0;
132	    }
133	
134	    for (let index = segmentStart; index < input.byteLength; index += 1) {
135	      const delimiter = input[index];
136	      if (delimiter !== 10 && delimiter !== 13) {
137	        continue;
138	      }
139	
140	      const segment = input.subarray(segmentStart, index);
141	      const completeLineBytes = byteLength + segment.byteLength;
142	      if (completeLineBytes > codexResponsesSseLineMaxBytes) {
143	        return yield* streamError(
144	          operation,
145	          "Codex Responses SSE line exceeded the configured byte limit."
146	        );
147	      }
148	      const completeParts =
149	        segment.byteLength === 0 ? parts : Chunk.append(parts, segment);
150	      const completeFragmentCount =
151	        segment.byteLength === 0 ? fragmentCount : fragmentCount + 1;
152	      if (completeFragmentCount > codexResponsesSseLineFragmentMaxCount) {
153	        return yield* streamError(
154	          operation,
155	          "Codex Responses SSE line exceeded the configured fragment limit."
156	        );
157	      }
158	      const value = yield* decodeLine(
159	        operation,
160	        completeParts,
161	        completeLineBytes
162	      );
163	
164	      parts = Chunk.empty();
165	      byteLength = 0;
166	      fragmentCount = 0;
167	      segmentStart = index + 1;
168	
169	      if (delimiter === 13 && index + 1 === input.byteLength) {
170	        pendingCarriageReturn = {
171	          value,
172	          contentByteLength: completeLineBytes,
173	        };
174	        continue;
175	      }
176	
177	      const isCarriageReturnLineFeed =
178	        delimiter === 13 && input[index + 1] === 10;
179	      emitted.push({
180	        _tag: "Line",
181	        value,
182	        wireByteLength: completeLineBytes + (isCarriageReturnLineFeed ? 2 : 1),
183	      });
184	      if (isCarriageReturnLineFeed) {
185	        index += 1;
186	        segmentStart = index + 1;
187	      }
188	    }
189	
190	    if (segmentStart < input.byteLength) {
191	      const residual = input.subarray(segmentStart);
192	      byteLength += residual.byteLength;
193	      fragmentCount += 1;
194	      if (byteLength > codexResponsesSseLineMaxBytes) {
195	        return yield* streamError(
196	          operation,
197	          "Codex Responses SSE line exceeded the configured byte limit."
198	        );
199	      }
200	      if (fragmentCount > codexResponsesSseLineFragmentMaxCount) {
201	        return yield* streamError(
202	          operation,
203	          "Codex Responses SSE line exceeded the configured fragment limit."
204	        );
205	      }
206	      parts = Chunk.append(parts, residual);
207	    }
208	
209	    const step: LineStep = [
210	      {
211	        byteLength,
212	        fragmentCount,
213	        parts,
214	        pendingCarriageReturn,
215	      },
216	      emitted,
217	    ];
218	    return step;
219	  });
220	
221	export const isCodexResponsesEventStream = (
222	  contentType: CodexHttpContentTypeHeader
223	) => contentType.split(";", 1)[0]?.trim().toLowerCase() === "text/event-stream";
224	
225	export const codexResponsesSseData = (
226	  source: Stream.Stream<Uint8Array, CodexResponsesStreamError>,
227	  operation: CodexResponsesStreamOperation
228	) => {
229	  const lines = source.pipe(
230	    Stream.map(
231	      (value): ByteInput => ({
232	        _tag: "Bytes",
233	        value,
234	      })
235	    ),
236	    Stream.concat(Stream.succeed<ByteInput>({ _tag: "End" })),
237	    Stream.mapAccumEffect(
238	      (): LineAccumulator => ({
239	        byteLength: 0,
240	        fragmentCount: 0,
241	        parts: Chunk.empty(),
242	        pendingCarriageReturn: undefined,
243	      }),
244	      (state, input) =>
245	        input._tag === "End"
246	          ? finishSseLines(operation, state)
247	          : splitSseBytes(operation, state, input.value)
248	    )
249	  );
250	
251	  return lines.pipe(
252	    Stream.mapAccumEffect(
253	      (): DataAccumulator => ({
254	        byteLength: 0,
255	        fieldCount: 0,
256	        parts: Chunk.empty(),
257	      }),
258	      (state, input) =>
259	        Effect.gen(function* frameSseEvent() {
260	          if (input._tag === "End") {
261	            if (state.byteLength > 0) {
262	              return yield* streamError(
263	                operation,
264	                "Codex Responses SSE stream ended with an incomplete event."
265	              );
266	            }
267	            const step: DataStep = [state, []];
268	            return step;
269	          }
270	
271	          const byteLength = state.byteLength + input.wireByteLength;
272	          if (byteLength > codexResponsesSseEventMaxBytes) {
273	            return yield* streamError(
274	              operation,
275	              "Codex Responses SSE event exceeded the configured byte limit."
276	            );
277	          }
278	
279	          if (input.value.length === 0) {
280	            const eventData =
281	              Chunk.size(state.parts) === 0
282	                ? []
283	                : [
284	                    yield* Schema.decodeUnknownEffect(
285	                      CodexResponsesSseDataPayload
286	                    )(Chunk.toReadonlyArray(state.parts).join("\n")).pipe(
287	                      Effect.mapError(() =>
288	                        streamError(
289	                          operation,
290	                          "Unable to decode Codex Responses SSE data."
291	                        )
292	                      )
293	                    ),
294	                  ];
295	            const step: DataStep = [
296	              { byteLength: 0, fieldCount: 0, parts: Chunk.empty() },
297	              eventData,
298	            ];
299	            return step;
300	          }
301	
302	          const fieldCount = state.fieldCount + 1;
303	          if (fieldCount > codexResponsesSseEventFieldMaxCount) {
304	            return yield* streamError(
305	              operation,
306	              "Codex Responses SSE event exceeded the configured field limit."
307	            );
308	          }
309	          if (!input.value.startsWith("data:")) {
310	            const step: DataStep = [{ ...state, byteLength, fieldCount }, []];
311	            return step;
312	          }
313	          const value = input.value.startsWith("data: ")
314	            ? input.value.slice("data: ".length)
315	            : input.value.slice("data:".length);
316	          const decodedValue = yield* Schema.decodeUnknownEffect(
317	            CodexResponsesSseDataPayload
318	          )(value).pipe(
319	            Effect.mapError(() =>
320	              streamError(
321	                operation,
322	                "Unable to decode Codex Responses SSE data."
323	              )
324	            )
325	          );
326	          const step: DataStep = [
327	            {
328	              byteLength,
329	              fieldCount,
330	              parts: Chunk.append(state.parts, decodedValue),
331	            },
332	            [],
333	          ];
334	          return step;
335	        })
336	    )
337	  );
338	};

