  1	import { Context, Effect, Redacted, Ref, Schema, Stream } from "effect";
  2	import { HttpClient, HttpClientRequest } from "effect/unstable/http";
  3	
  4	import { codexResponsesEndpointConfig } from "./config.js";
  5	import {
  6	  CodexResponsesProofResult,
  7	  CodexResponsesRequest,
  8	  CodexResponsesStreamMetadata,
  9	} from "./contracts.js";
 10	import type {
 11	  CodexResponsesPostInput,
 12	  CodexResponsesProofResult as CodexResponsesProofResultType,
 13	  CodexResponsesStreamResult,
 14	} from "./contracts.js";
 15	import {
 16	  CodexHttpContentTypeHeader,
 17	  CodexHttpStatus,
 18	} from "./error-contracts.js";
 19	import {
 20	  CodexHttpNetworkError,
 21	  CodexHttpStatusError,
 22	  CodexResponsesRequestError,
 23	  CodexResponsesStreamError,
 24	} from "./errors.js";
 25	import { codexResponsesSseData, isCodexResponsesEventStream } from "./sse.js";
 26	import {
 27	  advanceCodexResponsesStreamSequence,
 28	  decodeCodexResponsesStreamData,
 29	  initialCodexResponsesStreamSequenceState,
 30	} from "./stream-events.js";
 31	
 32	export type CodexHttpClientFailure =
 33	  | CodexResponsesRequestError
 34	  | CodexHttpNetworkError
 35	  | CodexHttpStatusError
 36	  | CodexResponsesStreamError;
 37	
 38	export interface CodexHttpClientShape {
 39	  readonly postResponses: (
 40	    input: CodexResponsesPostInput
 41	  ) => Effect.Effect<CodexResponsesProofResultType, CodexHttpClientFailure>;
 42	  readonly postResponsesStream: (
 43	    input: CodexResponsesPostInput
 44	  ) => Effect.Effect<CodexResponsesStreamResult, CodexHttpClientFailure>;
 45	}
 46	
 47	export class CodexHttpClient extends Context.Service<
 48	  CodexHttpClient,
 49	  CodexHttpClientShape
 50	>()("@bundjil/codex/CodexHttpClient") {}
 51	
 52	export const makeCodexHttpClient = Effect.gen(function* makeCodexHttpClient() {
 53	  const client = yield* HttpClient.HttpClient;
 54	  const endpoint = yield* codexResponsesEndpointConfig;
 55	
 56	  return CodexHttpClient.of({
 57	    postResponses: Effect.fn("CodexHttpClient.postResponses")(function* (
 58	      input: CodexResponsesPostInput
 59	    ) {
 60	      const encodedRequestBody = yield* Schema.encodeEffect(
 61	        Schema.fromJsonString(CodexResponsesRequest)
 62	      )(input.request).pipe(
 63	        Effect.mapError(
 64	          () =>
 65	            new CodexResponsesRequestError({
 66	              boundary: "CodexResponsesRequest",
 67	              message: "Unable to encode Codex Responses request.",
 68	            })
 69	        )
 70	      );
 71	      const headers = new Headers({
