134	export class CodexProxyConfig extends Context.Service<
135	  CodexProxyConfig,
136	  CodexProxyRuntimeConfigType
137	>()("@bundjil/codex-proxy/CodexProxyConfig") {}
138	
139	export const loadCodexProxyConfig = Effect.gen(
140	  function* loadCodexProxyConfigFromProvider() {
141	    const mode = yield* proxyModeConfig;
142	    const reasoningEffort = yield* reasoningEffortConfig;
143	    const internalToken = yield* internalTokenConfig;
144	    const profileId = yield* profileIdConfig;
145	    const connectorId = yield* connectorIdConfig;
146	    const installationId = yield* installationIdConfig;
147	    const subjectPrincipalId = yield* subjectPrincipalIdConfig;
148	    const accountId = yield* accountIdConfig;
149	    const localProfileStoreDirectory = yield* localProfileStoreDirectoryConfig;
150	    const vercelRuntimeMarker = yield* vercelRuntimeMarkerConfig;
151	    const subject = yield* decodeCodexOAuthSubject({
152	      connectorId,
153	      installationId,
154	      principal: {
155	        id: subjectPrincipalId,
156	        issuer: "https://auth.openai.com",
157	        type: "chatgpt-user",
158	      },
159	      profileId,
160	      provider: "codex",
161	    });
162	
163	    const config = yield* CodexProxyRuntimeConfig.makeEffect({
164	      mode,
165	      reasoningEffort,
166	      internalToken,
167	      subject,
168	      ...(Option.isNone(accountId) ? {} : { accountId: accountId.value }),
169	      ...(Option.isNone(localProfileStoreDirectory)
170	        ? {}
171	        : { localProfileStoreDirectory: localProfileStoreDirectory.value }),
172	    }).pipe(
173	      Effect.mapError(
174	        () =>
175	          new CodexProxyRouteError({
176	            boundary: "CodexProxyRuntimeConfig",
177	            code: "bad_request",
178	            message: "Unable to compose Codex proxy runtime config.",
179	            responseMessage: "The Codex proxy config is invalid.",
180	            status: 400,
181	          })
182	      )
183	    );
184	
185	    if (
186	      config.mode === "local" &&
187	      config.localProfileStoreDirectory === undefined
188	    ) {
189	      return yield* new CodexProxyRouteError({
190	        boundary: "CodexProxyRuntimeConfig",
191	        code: "bad_request",
192	        message:
193	          "Local Codex proxy mode requires a local profile store directory.",
194	        responseMessage: "The Codex proxy config is invalid.",
195	        status: 400,
196	      });
197	    }
198	
199	    if (config.mode === "local" && Option.isSome(vercelRuntimeMarker)) {
200	      return yield* new CodexProxyRouteError({
201	        boundary: "CodexProxyRuntimeConfig",
202	        code: "bad_request",
203	        message: "Local Codex proxy mode is unavailable in Vercel.",
204	        responseMessage: "The Codex proxy config is invalid.",
205	        status: 400,
206	      });
207	    }
208	
209	    return config;
210	  }
211	).pipe(
212	  Effect.withSpan("CodexProxyConfig.load"),
213	  Effect.provide(ConfigProvider.layerAdd(codexProxyConfigDefaults))
214	);
215	
216	export const loadCodexProxyConfigFromEnv = loadCodexProxyConfig.pipe(
217	  Effect.provide(ConfigProvider.layer(ConfigProvider.fromEnv()))
218	);
219	
220	export const loadCodexProxyDevServerConfig = Effect.gen(
221	  function* loadCodexProxyDevServerConfigFromProvider() {
222	    const port = yield* portConfig;
223	
224	    return yield* decodeCodexProxyDevServerConfig({ port });
225	  }
226	).pipe(Effect.withSpan("CodexProxyDevServerConfig.load"));
227	
228	export const loadCodexProxyDevServerConfigFromEnv =
229	  loadCodexProxyDevServerConfig.pipe(
230	    Effect.provide(ConfigProvider.layer(ConfigProvider.fromEnv()))
231	  );
232	
233	export const CodexProxyConfigLive = Layer.effect(
234	  CodexProxyConfig,
235	  loadCodexProxyConfig
236	).pipe(Layer.provide(ConfigProvider.layer(ConfigProvider.fromEnv())));
237	
238	export const CodexProxyConfigLayer = (config: CodexProxyRuntimeConfigType) =>
239	  Layer.succeed(CodexProxyConfig, config);
240	
241	export const makeCodexProxyConfig = (
242	  input: typeof CodexProxyRuntimeConfig.Encoded
243	) => decodeCodexProxyRuntimeConfig(input);
244	
245	export type { CodexProxyDevServerConfigType, CodexProxyRuntimeConfigType };

